{"file_path":"src/diff.js","content":"/**
 * Compute the changes between `base` and `side` (an array of lines each),
 * using a longest common subsequence over whole lines compared as exact
 * strings. Among LCS's of equal length, the one whose matches come as early
 * as possible (in the sense described in the task) is chosen, by walking
 * both sequences from the start and, on a mismatch, advancing whichever side
 * leaves at least as long a remaining LCS available, preferring to advance
 * the base on a tie.
 *
 * Returns a list of changes, each `{ baseStart, baseEnd, lines }`, in base
 * order, where `lines` are `side`'s lines that replace `base[baseStart,
 * baseEnd)`. An insertion has `baseStart === baseEnd`; a deletion has an
 * empty `lines`.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = dp[i]
    const nextRow = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) row[j] = nextRow[j + 1] + 1
      else row[j] = Math.max(nextRow[j], row[j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let prevI = 0
  let prevJ = 0

  while (i < n && j < m) {
    if (base[i] === side[j]) {
      if (i > prevI || j > prevJ) {
        changes.push({ baseStart: prevI, baseEnd: i, lines: side.slice(prevJ, j) })
      }
      i++
      j++
      prevI = i
      prevJ = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, lines: side.slice(prevJ, m) })
  }

  return changes
}
"}

