{"file_path":"src/merge.js","content":"import { computeChanges } from './diff.js'

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Group the changes from both sides into regions, per the task's absorption
 * rule: changes ordered by base start (mine before theirs on a tie), then
 * each region absorbs any following change that starts at or before its
 * current end.
 */
function buildRegions(mineChanges, theirsChanges) {
  const combined = []
  for (const c of mineChanges) combined.push({ ...c, side: 'mine' })
  for (const c of theirsChanges) combined.push({ ...c, side: 'theirs' })
  combined.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let idx = 0
  while (idx < combined.length) {
    const region = { start: combined[idx].baseStart, end: combined[idx].baseEnd, changes: [combined[idx]] }
    idx++
    while (idx < combined.length && combined[idx].baseStart <= region.end) {
      region.end = Math.max(region.end, combined[idx].baseEnd)
      region.changes.push(combined[idx])
      idx++
    }
    regions.push(region)
  }
  return regions
}

/**
 * Reconstruct one side's lines across a region: replay that side's own
 * changes in order, filling any gap between them (or before the first, or
 * after the last) with the corresponding, untouched base lines.
 */
function sideLines(base, region, side) {
  const changes = region.changes.filter(c => c.side === side).sort((a, b) => a.baseStart - b.baseStart)
  const lines = []
  let cursor = region.start
  for (const c of changes) {
    if (c.baseStart > cursor) lines.push(...base.slice(cursor, c.baseStart))
    lines.push(...c.lines)
    cursor = c.baseEnd
  }
  if (cursor < region.end) lines.push(...base.slice(cursor, region.end))
  return lines
}

/**
 * Resolve a region to `{ kind, lines }` where `kind` is one of `'mine'`,
 * `'theirs'`, `'both'` or `'conflict'`. A conflict additionally carries
 * `mineLines`, `baseLines` and `theirsLines`.
 */
function resolveRegion(base, region) {
  const mine = sideLines(base, region, 'mine')
  const theirs = sideLines(base, region, 'theirs')
  const baseLines = base.slice(region.start, region.end)

  if (linesEqual(mine, theirs)) return { kind: 'both', lines: mine }
  if (linesEqual(mine, baseLines)) return { kind: 'theirs', lines: theirs }
  if (linesEqual(theirs, baseLines)) return { kind: 'mine', lines: mine }
  return { kind: 'conflict', mineLines: mine, baseLines, theirsLines: theirs }
}

/**
 * Merge `mine`, `base` and `theirs` (arrays of lines). Returns a list of
 * segments in base order: `{ type: 'stable', lines }` for untouched base
 * spans, and `{ type: 'mine' | 'theirs' | 'both', lines }` or
 * `{ type: 'conflict', mineLines, baseLines, theirsLines }` for regions.
 */
export function merge(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegions(mineChanges, theirsChanges)

  const segments = []
  let cursor = 0
  for (const region of regions) {
    if (region.start > cursor) segments.push({ type: 'stable', lines: base.slice(cursor, region.start) })
    const resolved = resolveRegion(base, region)
    segments.push({ type: resolved.kind, ...resolved })
    cursor = region.end
  }
  if (cursor < base.length) segments.push({ type: 'stable', lines: base.slice(cursor) })

  return segments
}
"}

